-- AI opponent (docs/AI_OPPONENT.md §4a): the network's forward pass, plain Lua (MoonSharp).
-- A multilayer perceptron with ReLU hidden layers and one output: Q, the expected change in
-- the player's score margin (own score minus the best other) from now to the end of the
-- game if it takes this choice. Weights: ai.net_weights, generated by tools/ai_train.py.
--   weights = { version, inputs, layers = { { w = {...}, b = {...}, n_in, n_out }, ... },
--               mean = {...}, std = {...} }   (w row-major: w[(j - 1) * n_in + i])
--   or an ensemble: { version, inputs, features, members = { weights, weights, ... } } whose
--   Q is the average of its members' (each with its own input scaling); it steadies the
--   choice, which swings between networks trained alike

local M = {}

local loaded, weights = false, nil

function M.weights()
  if not loaded then
    loaded = true
    local ok, w = pcall(require, "ai.net_weights")
    if ok and type(w) == "table" and (w.layers or w.members) then weights = w end
  end
  return weights
end

function M.set_weights(w)          -- tests and training
  loaded, weights = true, w
end

function M.available()
  return M.weights() ~= nil
end

-- x: the input list (features.state .. features.choice); returns Q
function M.forward(x, w)
  w = w or M.weights()
  if w.members then
    local sum = 0
    for _, member in ipairs(w.members) do sum = sum + M.forward(x, member) end
    return sum / #w.members
  end
  local cur = {}
  for i = 1, w.inputs do
    local s = w.std[i]
    cur[i] = ((x[i] or 0) - w.mean[i]) / ((s ~= nil and s > 0) and s or 1)
  end
  local layers = w.layers
  for l = 1, #layers do
    local layer = layers[l]
    local wt, b, n_in, n_out = layer.w, layer.b, layer.n_in, layer.n_out
    local out = {}
    local last = (l == #layers)
    for j = 1, n_out do
      local s, base = b[j], (j - 1) * n_in
      for i = 1, n_in do
        local v = cur[i]
        if v ~= 0 then s = s + wt[base + i] * v end
      end
      if not last and s < 0 then s = 0 end
      out[j] = s
    end
    cur = out
  end
  return cur[1]
end

return M
